mapper.select:


     and A.customer_name like concat('%', #{brtCustomerVo.customerName}, '%')
     and A.customer_no = #{brtCustomerVo.customerNo}
     and A.type_id = #{brtCustomerVo.typeId}
     and A.grade_id = #{brtCustomerVo.gradeId}
     and A.contact like concat('%',#{brtCustomerVo.contact},'%')
     and A.contact_tel like concat('%',#{brtCustomerVo.contactTel},'%')
     and A.user_id = #{brtCustomerVo.userId}
     and A.customer_remark = #{brtCustomerVo.customerRemark}
     and A.attachments = #{brtCustomerVo.attachments}
     and A.customer_status = #{brtCustomerVo.customerStatus}

        and (A.customer_name like concat('%', #{brtCustomerVo.keyWords}, '%') or A.customer_no like concat('%', #{brtCustomerVo.keyWords}, '%'))




                and date_format(A.create_time,'%y%m%d') = date_format(now(),'%y%m%d')


                and DATE(A.create_time) = CURDATE() - INTERVAL 1 DAY


                and date_format(A.create_time,'%y%m') = date_format(now(),'%y%m')


                and QUARTER(A.create_time) = QUARTER(CURDATE()) and YEAR(A.create_time) = YEAR(CURDATE())


                and YEAR(A.create_time) = YEAR(CURDATE())




        and date_format(A.create_time,'%y%m%d') between date_format(#{brtCustomerVo.createTimeStart},'%y%m%d') and date_format(#{brtCustomerVo.createTimeEnd},'%y%m%d')


        and customer_id in

            #{item}



    ${brtCustomerVo.params.brtDataScope}



order by A.create_time desc
